CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '', platform text NOT NULL DEFAULT 'ESP32', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_owner ON projects(owner_id);
CREATE TABLE IF NOT EXISTS project_members(project_id uuid REFERENCES projects ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS project_files(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, name text NOT NULL, category text NOT NULL CHECK(category IN ('firmware','schematic','datasheet','measurement','log','document')), storage_key text NOT NULL UNIQUE, sha256 text NOT NULL, size bigint NOT NULL CHECK(size>0), status text NOT NULL DEFAULT 'queued', error text NOT NULL DEFAULT '', analysis jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS files_project ON project_files(project_id);
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY REFERENCES project_files ON DELETE CASCADE, pages int NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS document_chunks(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents ON DELETE CASCADE, page int NOT NULL, content text NOT NULL, embedding vector(384));
CREATE INDEX IF NOT EXISTS chunks_document ON document_chunks(document_id);
CREATE TABLE IF NOT EXISTS investigations(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, problem text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','investigating','waiting_for_measurement','resolved','closed')), resolution text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS investigations_project ON investigations(project_id);
CREATE TABLE IF NOT EXISTS investigation_evidence(investigation_id uuid REFERENCES investigations ON DELETE CASCADE, file_id uuid REFERENCES project_files ON DELETE CASCADE, PRIMARY KEY(investigation_id,file_id));
CREATE TABLE IF NOT EXISTS diagnostic_hypotheses(id uuid PRIMARY KEY, investigation_id uuid NOT NULL REFERENCES investigations ON DELETE CASCADE, rule_key text NOT NULL, title text NOT NULL, rank int NOT NULL, assessment jsonb NOT NULL, status text NOT NULL DEFAULT 'unverified' CHECK(status IN ('unverified','supported','confirmed','rejected')), UNIQUE(investigation_id,rule_key));
CREATE TABLE IF NOT EXISTS diagnostic_tests(id uuid PRIMARY KEY, hypothesis_id uuid NOT NULL REFERENCES diagnostic_hypotheses ON DELETE CASCADE, observation text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('supports','confirms','rejects','inconclusive')), recorded_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS measurement_files(id uuid PRIMARY KEY REFERENCES project_files ON DELETE CASCADE, metadata jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS measurement_results(id uuid PRIMARY KEY, file_id uuid NOT NULL REFERENCES measurement_files ON DELETE CASCADE, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS components(id uuid PRIMARY KEY, file_id uuid NOT NULL REFERENCES project_files ON DELETE CASCADE, reference text NOT NULL, properties jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_entries(id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects ON DELETE CASCADE, investigation_id uuid REFERENCES investigations ON DELETE SET NULL, title text NOT NULL, content text NOT NULL, embedding vector(384), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS background_jobs(id uuid PRIMARY KEY, file_id uuid NOT NULL REFERENCES project_files ON DELETE CASCADE, status text NOT NULL DEFAULT 'queued', attempts int NOT NULL DEFAULT 0, error text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_status ON background_jobs(status,updated_at);
CREATE TABLE IF NOT EXISTS investigation_events(id uuid PRIMARY KEY, investigation_id uuid NOT NULL REFERENCES investigations ON DELETE CASCADE, kind text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
